#include <vector>

class Solution {
public:
    int returnToBoundaryCount(std::vector<int>& nums) {
        int pos = 0, ans = 0;
        for (int x : nums) {
            pos += x;
            if (pos == 0) ans++;
        }
        return ans;
    }
};

class Solution {
    public int returnToBoundaryCount(int[] nums) {
        int pos = 0, ans = 0;
        for (int x : nums) {
            pos += x;
            if (pos == 0) ans++;
        }
        return ans;
    }
}

